1249 /// If we have a select with an equality comparison, then we know the value in
1250 /// one of the arms of the select. See if substituting this value into an arm
1251 /// and simplifying the result yields the same value as the other arm.
1252 ///
1253 /// To make this transform safe, we must drop poison-generating flags
1254 /// (nsw, etc) if we simplified to a binop because the select may be guarding
1255 /// that poison from propagating. If the existing binop already had no
1256 /// poison-generating flags, then this transform can be done by instsimplify.
1257 ///
1258 /// Consider:
1259 ///   %cmp = icmp eq i32 %x, 2147483647
1260 ///   %add = add nsw i32 %x, 1
1261 ///   %sel = select i1 %cmp, i32 -2147483648, i32 %add
1262 ///
1263 /// We can't replace %sel with %add unless we strip away the flags.
1264 /// TODO: Wrapping flags could be preserved in some cases with better analysis.
1265 Instruction *InstCombinerImpl::foldSelectValueEquivalence(SelectInst &Sel,
1266                                                           ICmpInst &Cmp) {
1267   if (!Cmp.isEquality())
1268     return nullptr;
1269 
1270   // Canonicalize the pattern to ICMP_EQ by swapping the select operands.
1271   Value *TrueVal = Sel.getTrueValue(), *FalseVal = Sel.getFalseValue();
1272   bool Swapped = false;
1273   if (Cmp.getPredicate() == ICmpInst::ICMP_NE) {
1274     std::swap(TrueVal, FalseVal);
1275     Swapped = true;
1276   }
1277 
1278   // In X == Y ? f(X) : Z, try to evaluate f(Y) and replace the operand.
1279   // Make sure Y cannot be undef though, as we might pick different values for
1280   // undef in the icmp and in f(Y). Additionally, take care to avoid replacing
1281   // X == Y ? X : Z with X == Y ? Y : Z, as that would lead to an infinite
1282   // replacement cycle.
1283   Value *CmpLHS = Cmp.getOperand(0), *CmpRHS = Cmp.getOperand(1);
1284   if (TrueVal != CmpLHS &&
1285       isGuaranteedNotToBeUndefOrPoison(CmpRHS, SQ.AC, &Sel, &DT)) {
1286     if (Value *V = simplifyWithOpReplaced(TrueVal, CmpLHS, CmpRHS, SQ,
1287                                           /* AllowRefinement */ true))
1288       // Require either the replacement or the simplification result to be a
1289       // constant to avoid infinite loops.
1290       // FIXME: Make this check more precise.
1291       if (isa<Constant>(CmpRHS) || isa<Constant>(V))
1292         return replaceOperand(Sel, Swapped ? 2 : 1, V);
1293 
1294     // Even if TrueVal does not simplify, we can directly replace a use of
1295     // CmpLHS with CmpRHS, as long as the instruction is not used anywhere
1296     // else and is safe to speculatively execute (we may end up executing it
1297     // with different operands, which should not cause side-effects or trigger
1298     // undefined behavior). Only do this if CmpRHS is a constant, as
1299     // profitability is not clear for other cases.
1300     // FIXME: Support vectors.
1301     if (match(CmpRHS, m_ImmConstant()) && !match(CmpLHS, m_ImmConstant()) &&
1302         !Cmp.getType()->isVectorTy())
1303       if (replaceInInstruction(TrueVal, CmpLHS, CmpRHS))
1304         return &Sel;
1305   }
1306   if (TrueVal != CmpRHS &&
1307       isGuaranteedNotToBeUndefOrPoison(CmpLHS, SQ.AC, &Sel, &DT))
1308     if (Value *V = simplifyWithOpReplaced(TrueVal, CmpRHS, CmpLHS, SQ,
1309                                           /* AllowRefinement */ true))
1310       if (isa<Constant>(CmpLHS) || isa<Constant>(V))
1311         return replaceOperand(Sel, Swapped ? 2 : 1, V);
1312 
1313   auto *FalseInst = dyn_cast<Instruction>(FalseVal);
1314   if (!FalseInst)
1315     return nullptr;
1316 
1317   // InstSimplify already performed this fold if it was possible subject to
1318   // current poison-generating flags. Check whether dropping poison-generating
1319   // flags enables the transform.
1320 
1321   // Try each equivalence substitution possibility.
1322   // We have an 'EQ' comparison, so the select's false value will propagate.
1323   // Example:
1324   // (X == 42) ? 43 : (X + 1) --> (X == 42) ? (X + 1) : (X + 1) --> X + 1
1325   SmallVector<Instruction *> DropFlags;
1326   if (simplifyWithOpReplaced(FalseVal, CmpLHS, CmpRHS, SQ,
1327                              /* AllowRefinement */ false,
1328                              &DropFlags) == TrueVal ||
1329       simplifyWithOpReplaced(FalseVal, CmpRHS, CmpLHS, SQ,
1330                              /* AllowRefinement */ false,
1331                              &DropFlags) == TrueVal) {
1332     for (Instruction *I : DropFlags) {
1333       I->dropPoisonGeneratingFlagsAndMetadata();
1334       Worklist.add(I);
1335     }
1336 
1337     return replaceInstUsesWith(Sel, FalseVal);
1338   }
1339 
1340   return nullptr;
1341 }
